Read the following passage and answer the question that follows.

A program stores student records in a binary file and later reads them back:

import pickle
recs = [[1, 'Asha', 82], [2, 'Bilal', 67], [3, 'Chen', 91]]
with open('stu.dat', 'wb') as f:
    for r in recs:
        pickle.dump(r, f)

def show(minm):
    count = 0
    with open('stu.dat', 'rb') as f:
        try:
            while True:
                r = pickle.load(f)
                if r[2] > minm:
                    print(r[1], end=' ')
                    count += 1
        except EOFError:
            pass
    return count

